function cancelWork(){epoch++;sliderArmed=false;const sliderId=sliderDrag?.id;sliderDrag=null;if(sliderId!==undefined&&slider.hasPointerCapture(sliderId))slider.releasePointerCapture(sliderId);driftRemaining=0;helm=false;routeAuthority=false;planAssist=false;request?.abort();request=null;scene.cancelGesture();document.body.classList.remove('handle-busy');$('#execution-notice').textContent='';}
function pause(keep=false){cancelWork();fuelRevisionPending=false;fieldGoal=null;document.body.classList.remove('handle-busy');request?.abort();request=null;$('#execution-notice').textContent='';game.pause();handleEditing=false;if(!keep){quote=null;preview=null;comparison=null;tracers=null;fieldEdit=null;}else if(quote?.kind.startsWith('gravity-')&&!game.view().target){const q=quote;try{setQuote(game.fieldQuote({destination:destinationOf(q),speed:q.detail.requestedSpeed,centerShip:q.detail.centerShip}));}catch{quote=null;preview=null;}}render();}
