function renderRouteBudget(){
 const q=quote,v=game.view(),show=!!q?.kind.startsWith('gravity-');$('#route-budget').hidden=!show;if(!show)return;
 const total=q.detail.miningComparison?.totalFuelSpent??q.cost.fuel+q.detail.braking,years=q.detail.miningComparison?.totalYears??q.detail.years,b=routeBaseline;
 $('#route-bars').innerHTML=[['Fuel',v.budget.fuel,v.spent.fuel+total,b.spent.fuel+b.fuel,'fuel',2],['Years',v.budget.lifetime,v.spent.lifetime+years,b.spent.lifetime+b.years,'years',1]].map(([label,cap,used,original,unit,n])=>{const left=cap-used,pct=cap?100*used/cap:100,mark=cap?100*original/cap:100;return `<div class="resource-row"><div><span>${label} · ${fmt(used-(unit==='fuel'?v.spent.fuel:v.spent.lifetime),n)} / ${fmt(cap-(unit==='fuel'?v.spent.fuel:v.spent.lifetime),n)}</span><strong class="${left<0?'bad':''}">${fmt(left,n)} cap left</strong></div><div class="resource-track ${left<0?'over-budget':''}" role="img" aria-label="Projected ${fmt(used,n)} of ${fmt(cap)} ${unit} used; ${fmt(left,n)} left. Original route ${fmt(original,n)}."><span style="width:${Math.max(0,Math.min(100,pct))}%"></span><i style="left:${Math.max(0,Math.min(100,mark))}%"></i></div></div>`;}).join('');
 const saved=b.fuel-total,extra=years-b.years;$('#route-tradeoff').textContent=` ${fmt(Math.abs(saved),2)} fuel ${saved>=0?'saved':'more'} · ${fmt(Math.abs(extra),1)} ${extra>=0?'extra':'fewer'} years vs original`;
 const setting=(.07-q.detail.requestedSpeed)/.05*1000;$('#field-strength').value=setting;$('#field-setting').textContent=`${(setting/10).toFixed(1)}%`;
 $('#field-strength').setAttribute('aria-valuetext',`${fmt(setting/10,1)} percent toward less fuel. ${fmt(total,2)} fuel including braking, ${fmt(years)} years.`);
}
function renderControls(){syncControls({interaction:scene.mode,view:game.view(),delegated:helm,planning:planAssist,request,pending:fuelRevisionPending,accepted:acceptedFuelRevision,quote,editing:handleEditing,error:uiError});}
function render(){renderShell();renderMissionOffer();renderRouteBudget();const v=game.view();$('#mission-change').hidden=!v.calibration||['arrived','mined'].includes(v.phase);$('#mission-change').textContent=v.objective==='yolo'?'Choose another asteroid':'Home can wait · YOLO';$('#mission-home').hidden=v.objective==='home'||['arrived','mined'].includes(v.phase);$('#visit-star').hidden=!v.calibration||v.phase==='arrived';$('#visit-star').textContent=`Visit HIP ${v.identifiedLights.find(l=>l.observationId===selected)?.catalogueId??v.destinationStar?.id??''}`;$('#browse-sky').hidden=!['at-star'].includes(v.phase);for(const m of ['plan','drive']){$('#'+m+'-mode').classList.toggle('active',v.mode===m);$('#'+m+'-mode').setAttribute('aria-pressed',String(v.mode===m));}$('#help-plan').hidden=v.mode!=='plan'||!!v.calibration||!replayChapter;$('#help-plan').disabled=!!request||v.phase==='arrived';$('#help-plan').textContent=v.calibration?'Help me plan':`Help me plan · ${v.calibrationCredits} credits`;document.body.dataset.mode=v.mode;document.body.classList.toggle('arrived',v.phase==='arrived'&&!skyExploration);if(v.phase==='arrived'&&!skyExploration){selected=null;$('#star-context').hidden=true;}for(const k of ['fuel','credits','lifetime']){$('#'+k).textContent=fmt(v.resources[k]);$('#budget-'+k).disabled=v.active||!!request;}$('#budget-spend').textContent=hasDelegated?`${fmt(v.spent.fuel)} fuel · ${fmt(v.spent.credits)} credits · ${fmt(v.spent.lifetime)} years used`:'Spending limits';$('#interrupt').disabled=!v.active&&!request;$('#undo').disabled=!v.canUndo;$('#map-legend').innerHTML=attemptPath?`<span style="color:#e5bc8f">Your proposed push</span>${comparison?.sameState?'<span style="color:#c2d4ff">Astra’s alternative</span>':''}${previousAlternativePath?'<span style="color:#89a5c9">Earlier field preview</span>':''}<span style="color:#a8b2c5">Original motion</span>`:'';renderControls();
 if(lastSkyTime!==v.time){scene.setSky(game.sky());lastSkyTime=v.time;}$('#scene-title').textContent=v.phase==='arrived'?(skyExploration?'The sky from Earth.':"You’re home."):v.phase==='at-star'?`${v.destinationStar.name} · arrival verified`:v.objective==='explore'?`Set course for ${v.destinationStar.name}`:v.objective==='yolo'?(v.target?`Heading to ${v.report.name}`:'Home can wait.'):v.target?(v.target.name==='asteroid'?'Heading to the asteroid':v.target.name==='star'?`Heading to ${v.destinationStar.name}`:'Heading home'):(v.calibration?'Shape your way home':'Find your way home.');$('#scene-description').textContent=skyExploration?(constellationSelection?`${constellationSelection.name} members in the local sky. Move view to look around.`:'Look around, or browse the full constellation atlas.'):v.phase==='arrived'?'':v.target?'':v.calibration?'Drag the grip · travel distances are simulated.':'Select a ringed star.';$('#select-mode').disabled=skyExploration||v.phase==='arrived';$('#brush-mode').disabled=skyExploration||v.phase==='arrived';$('#scene-caption').textContent=v.phase==='arrived'?'':v.mode==='plan'?'':v.active?'':quote?`Release applies · ${fmt(quote.cost.fuel,2)} fuel${quote.kind==='experiment'?' · 2 years flight':''}`:'Drive · release applies the quote';$('#investigate-stop').hidden=v.objective!=='home'||!v.calibration||!!v.target||v.phase==='arrived'||!!v.report||!lastProposal;$('#investigate-stop').disabled=!!request||v.active;const origin=v.calibration?.position,shipOffset=origin?game.shipVector(V.sub(v.position,origin)):v.localPosition;scene.set({view:v,skyExploration,constellationStars:constellationSelection?.stars??[],starOffset:v.calibration?game.shipVector(V.sub(v.destinationStar.cataloguePosition,v.position)):null,preview,previewKind:quote?.kind,comparison,attemptPath,previousAlternativePath,stroke,selected,evidenceVisible:quote?.kind==='calibrate'||replayChapter==='locate'&&!!v.calibration,fieldQuote:quote?.kind.startsWith('gravity-')?quote:null,handleY:fieldEdit?.handleY??0,fieldOffset:fieldEdit?.offset??[0,0,0],tracers,flightPath,shipOffset,homeDirection:v.calibration?game.shipVector(V.scale(v.position,-1)):null,homeOrigin:origin?game.shipVector(V.scale(origin,-1)):null,homeDistance:v.homeDistance,previewTarget:['gravity-stop','gravity-star'].includes(quote?.kind)?game.shipVector(V.sub(quote.detail.destination,v.position)):null,asteroidOffset:v.report?game.shipVector(V.sub(v.report.position,v.position)):null,routePath:v.target?game.routePath():null,fieldProgress:v.field?(v.time-v.field.start)/(v.field.until-v.field.start):null});
 $('#measurements').innerHTML=v.identifiedLights.map(l=>`<p>Selected light: <b>HIP ${l.catalogueId}</b> · synthetic spectral tag. Identity alone is not a position fix.</p>`).join('')+`<p>${v.calibration?`Four ranges solved position and bearings solved attitude. Held-out residual: ${v.calibration.heldOutResidual.toExponential(2)} ly in the ideal model.`:'Only bearings are available. Range, position and home direction remain unresolved.'}</p>`+v.observations.map(o=>`<p><b>${o.label}</b> · ${o.catalogueId?'Catalogue '+o.catalogueId:'unidentified'} · bearing [${o.bearing.map(n=>fmt(n,3)).join(', ')}]${o.range?' · '+fmt(o.range,5)+' ly':''}</p>`).join('');$('#ledger-count').textContent=`${v.ledger.length} actions`;$('#ledger').innerHTML=v.ledger.map(l=>`<tr><td>${esc(names[l.kind])}</td><td>${fmt(l.cost.fuel,3)} / ${fmt(l.reward.fuel,3)}</td><td>${fmt(l.cost.credits)} / ${fmt(l.reward.credits)}</td><td>${fmt(l.cost.lifetime,3)}</td></tr>`).join('');
 if(v.phase==='arrived')card({state:'Arrival verified',title:'',description:'',metrics:[['Fuel left',fmt(v.resources.fuel,2)],['Years left',fmt(v.resources.lifetime)]],actions:[['Inspect receipt',openDetails],['Browse constellations',openSky]],evidence:`Final distance ${v.homeDistance.toExponential(3)} ly. Relative speed ${V.norm(v.velocity).toExponential(3)} ly/year. Gross spent ${fmt(v.spent.fuel,3)} fuel, ${fmt(v.spent.credits)} credits. Every reward came from the finite deposit and every debit appears in the ledger.`});
}
function brush(impulse,released){if(game.view().target||game.view().phase==='arrived')return;if(game.view().active||request)pause();try{syncBudget();stroke=impulse;const q=released?quote:game.rawQuote({impulse,flightYears:2});if(!q||q.kind!=='experiment')return;if(!released)setQuote(q);if(released){game.rememberAttempt(q.id);attemptPath=game.preview(q.id,{frame:'ship',years:2}).proposed.path;if(game.view().mode==='drive'){applyBrush();return;}say('Your push is kept as a free preview. Let’s find out whether it points us toward home.','PREVIEW · NO RESOURCES SPENT');render();}}catch(e){fail(e);}}
function syncBudget(){game.setBudget(Object.fromEntries(['fuel','credits','lifetime'].map(k=>[k,Number($('#budget-'+k).value)])));}
function establishBudget(){syncBudget();hasDelegated=true;game.resume();}
function commitReviewed(q,{source='human',enterDrive=false,investigation=false,token=epoch}={}){
 if(!q||token!==epoch)throw Error('Expired action');
 const mode=game.view().mode;
 if(source==='astra'&&!(mode==='drive'&&helm)&&!(mode==='plan'&&planAssist&&investigation&&q.kind==='calibrate'))throw Error('Astra has no execution authority');
 if(source==='route'&&!(mode==='drive'&&routeAuthority))throw Error('Route is paused');
 const result=game.commit(q.id,{manual:source==='human',enterDrive,investigation});
 return result;
}
function beginGesture(){const old=quote,edit=fieldEdit;pause(true);syncBudget();handleEditing=true;if(old?.kind.startsWith('gravity-'))setQuote(game.fieldQuote({destination:destinationOf(old),speed:old.detail.requestedSpeed,centerShip:old.detail.centerShip}));if(edit&&fieldEdit)Object.assign(fieldEdit,{offset:edit.offset,handleY:edit.handleY});render();}
function applyBrush(){if(quote?.kind!=='experiment')return;try{const q=quote;cancelWork();commitReviewed(q,{enterDrive:game.view().mode==='plan'});hasDelegated=true;routeAuthority=true;driftRemaining=q.detail.flightYears;flightPath=preview?.proposed.path;quote=null;preview=null;say('Push applied. Flying the quoted two-year preview; Interrupt pauses at a checkpoint.','DRIVING');render();proceed(epoch);}catch(e){fail(e);}}
function editField(speed,offset=null,dy=0){try{offset=offset??fieldEdit?.offset??[0,0,0];const destination=fieldEdit?.destination??'home';let q=game.fieldQuote({destination,speed});const manual=V.norm(offset)>1e-10;if(manual)q=game.fieldQuote({destination,speed,centerShip:V.add(q.detail.centerShip,offset)});setQuote(q);fieldEdit.manual=manual;fieldEdit.offset=[...offset];fieldEdit.handleY=dy;render();}catch(e){say(e.message,'FIELD PREVIEW');}}
async function releaseField(source,apply=false){if(!quote?.kind.startsWith('gravity-'))return;handleEditing=false;if(game.view().mode==='plan'&&!apply){say('Preview updated.','PREVIEW');render();return;}
 try{const q=quote;if(source==='human')cancelWork();commitReviewed(q,{source,enterDrive:apply&&game.view().mode==='plan'});hasDelegated=true;routeAuthority=true;automaticMining=q.kind==='gravity-stop';plannedOnward=automaticMining&&game.view().objective==='home';flightPath=preview?.proposed.path;fieldGoal=null;document.body.classList.remove('handle-busy');quote=null;preview=null;comparison=null;say('Field applied. The ship now follows the computed force.','DRIVING');render();return proceed(epoch);}catch(e){fail(e);}}
function candidates(){const list=[];if(game.view().objective!=='explore'&&game.view().report&&!game.view().target&&['calibrated','at-stop'].includes(game.view().phase)&&game.view().preference!=='less-fuel'){try{const q=game.fieldQuote({destination:'asteroid',speed:.025});list.push({...q,assessment:game.assess(q.id)});}catch{}}if(lastProposal?.kind.startsWith('gravity-')&&['calibrated','at-stop'].includes(game.view().phase)&&!game.view().target){try{const q=game.fieldQuote({destination:destinationOf(lastProposal),speed:lastProposal.detail.requestedSpeed,centerShip:lastProposal.detail.centerShip});list.push({...q,currentPreview:true,assessment:game.assess(q.id)});}catch{}}for(const kind of game.options()){try{const q=game.quote(kind);list.push({...q,assessment:game.assess(q.id)});}catch{}}return list;}
function makeRequest(message,qs){const v=game.view(),a=game.attempt();return {requestId:crypto.randomUUID(),revision:v.revision,message,history:history.slice(-16),observation:{objective:v.objective,destinationStarId:v.calibration?v.destinationStar.id:null,selectedAsteroidId:v.objective==='yolo'?v.report?.id??null:null,phase:v.phase,delegated:helm&&v.mode==='drive',planning:planAssist&&v.mode==='plan',resources:v.resources,budgetRemaining:Object.fromEntries(Object.keys(v.budget).map(k=>[k,Math.max(0,v.budget[k]-v.spent[k])])),preference:v.preference,landmarks:v.observations,navigation:v.calibration?{distance:v.homeDistance,speed:V.norm(v.velocity),target:v.target?.name??'none',remaining:v.target?.remaining??0,calibrationResidual:v.calibration.residual}:null,asteroid:v.report?{relativePosition:V.sub(v.report.position,v.position),velocity:v.report.velocity,radiusKm:v.report.radiusKm,operationRadiusLy:v.report.operationRadiusLy,spinPeriodHours:v.report.spinPeriodHours,grossFuel:v.deposit.fuel,grossCredits:v.deposit.credits,extractionFuel:3,extractionCredits:2,extractionYears:2,reportCreditsPaid:v.report.reportCreditsPaid??3}:null,attempt:a?{impulse:a.impulse,fuel:a.cost.fuel,years:2,committed:a.committed}:null},choices:qs.map(q=>{const pr=game.preview(q.id,{frame:'ship',years:2}),cmp=(q.kind.startsWith('gravity-')||q.kind.startsWith('launch-'))?game.compareAttempt(q.id,{years:2}):null;return {id:q.id,currentPreview:!!q.currentPreview,kind:q.kind,cost:q.cost,summary:q.detail.summary.slice(0,400),years:q.detail.years??0,reserve:q.detail.reserve??0,affordable:q.assessment.affordable,reason:q.assessment.reason,evidence:{impulse:q.detail.impulse??[0,0,0],gravityBefore:q.detail.gravityBefore??0,gravityAfter:q.detail.gravityAfter??0,gravityDuration:q.detail.gravityDuration??0,braking:q.detail.braking??0,speed:q.detail.speed??0,endpointSeparation:pr?V.norm(V.sub(pr.current.p,pr.proposed.p)):0,grossFuel:q.reward.fuel,grossCredits:q.reward.credits},field:q.kind.startsWith('gravity-')?{centerShip:q.detail.centerShip,duration:q.detail.duration,strength:q.detail.strength,miss:q.detail.miss,fullTripFuel:q.detail.miningComparison?.totalFuelSpent??q.cost.fuel+q.detail.braking,fullTripYears:q.detail.miningComparison?.totalYears??q.detail.years,fullTripCredits:q.detail.miningComparison?2:0,onwardMode:q.kind==='gravity-stop'?(v.objective==='yolo'?'choose-next':'direct-slow'):'none'}:null,comparison:cmp?.sameState?{years:cmp.years,attemptFuel:cmp.attemptFuel,alternativeFuel:cmp.alternativeFuel,attemptHomeProgress:cmp.attemptHomeProgress,alternativeHomeProgress:cmp.alternativeHomeProgress}:null};})};}
async function decide(message='Continue the delegated plan from the supplied evidence.',observeOnly=false){const token=epoch;if(!helm&&!planAssist&&!observeOnly)return;const qs=candidates();if(!qs.length&&!observeOnly)return fail(Error('Choose a destination to preview the next route.'));const body=makeRequest(message,qs),ctrl=new AbortController();request=ctrl;render();try{let res;for(let retry=0;retry<21;retry++){res=await fetch('/api/journey',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctrl.signal});if(res.status!==409)break;await new Promise(r=>setTimeout(r,5000));if(token!==epoch)return;}const data=await res.json();if(token!==epoch||game.revision!==body.revision)return;if(!res.ok)throw Error(data.message||'Live Astra unavailable');if(data.requestId!==body.requestId||data.revision!==body.revision||data.model!=='gpt-6-astra')throw Error('Stale model reply rejected');request=null;const p=data.proposal;say(p.summary);if(observeOnly){if(p.preference!=='keep')game.preference(p.preference);fuelRevisionPending=false;render();return;}if(p.preference==='skip-stop'&&game.view().objective!=='home'){pause(true);say('Use Plot a course home to change the mission.','PLAN');return;}if(p.preference==='skip-stop'&&p.preference!==game.view().preference){const before=lastProposal;game.preference('skip-stop');automaticMining=false;plannedOnward=false;if(before?.kind==='gravity-home')setQuote(game.fieldQuote({speed:before.detail.requestedSpeed,centerShip:before.detail.centerShip}));else if(game.view().calibration)setQuote(game.fieldQuote({destination:'home'}));say('Stop declined. The report cost remains spent.','PLAN');return decide('The stop is declined. Keep the current direct preview and the human’s stated constraints. Remain in the current mode.');}if(p.preference!=='keep'&&p.preference!==game.view().preference){const before=game.view().target?null:(lastProposal?.kind.startsWith('gravity-')?lastProposal:qs.find(q=>q.kind==='gravity-home'));if(before){const old=game.fieldQuote({destination:destinationOf(before),speed:before.detail.requestedSpeed,centerShip:before.detail.centerShip});previousAlternativePath=game.preview(old.id,{frame:'ship',years:2}).proposed.path;}game.preference(p.preference);if(before){const after=p.preference==='skip-stop'?game.fieldQuote(before.kind==='gravity-home'?{speed:before.detail.requestedSpeed,centerShip:before.detail.centerShip}:{destination:'home'}):game.quote(before.kind);const change={kind:before.kind,before:{fuel:before.cost.fuel+before.detail.braking,years:before.detail.years,speed:before.detail.requestedSpeed??before.detail.speed,center:before.detail.centerShip},after:{fuel:after.cost.fuel+after.detail.braking,years:after.detail.years,speed:after.detail.requestedSpeed??after.detail.speed,center:after.detail.centerShip}};recordedComparisons.push(change);setQuote(after);say(`Changed the control: ${fmt(change.before.fuel,2)} → ${fmt(change.after.fuel,2)} fuel including this leg’s brake; ${fmt(change.before.years)} → ${fmt(change.after.years)} years. The field and route preview now use the revised setting.`,'COMPUTED CHANGE');}return decide('The human priority is now applied. Use the current preview and latest stated constraints; remain in the current Plan or delegated Drive mode.');}
 if(p.actionId===null){fuelRevisionPending=false;pause(true);return;}const chosen=qs.find(q=>q.id===p.actionId);if(!chosen||!chosen.assessment.affordable)throw Error('Unsupported or unaffordable action rejected');fuelRevisionPending=false;setQuote(chosen);if(game.view().mode==='plan'&&chosen.kind!=='calibrate'){render();return;}if(chosen.kind.startsWith('gravity-'))return await astraField(chosen,token);return await schedule(chosen,token);
 }catch(e){if(e.name!=='AbortError'&&token===epoch)fail(e);}finally{if(request===ctrl)request=null;render();}}
async function waitPreview(seconds,token){advance=false;const start=performance.now();while(!advance&&performance.now()-start<seconds*1000){if(token!==epoch||!(game.view().active||planAssist))return false;$('#execution-notice').textContent=`${quote?.kind.startsWith('gravity-')?'Astra moves the handle':'Next action'} in ${Math.max(0,Math.ceil(seconds-(performance.now()-start)/1000))} s · Interrupt to revise`;await new Promise(r=>setTimeout(r,80));}$('#execution-notice').textContent='';return token===epoch&&(game.view().active||planAssist);}
async function astraField(q,token){await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(token!==epoch||!game.view().active)return;if(!await waitPreview(20,token))return;fieldGoal=q;document.body.classList.add('handle-busy');const target=q.detail.requestedSpeed,begin=Math.min(.065,target+.018);const destination=destinationOf(q),guided=game.fieldQuote({destination,speed:target});fieldEdit={destination,speed:begin,offset:V.sub(q.detail.centerShip,guided.detail.centerShip)};say('We can reshape the field here. I’m moving the same handle you can drag.','DELEGATED FIELD CONTROL');const duration=scene.reduced?0:3000,start=performance.now();do{if(token!==epoch||!game.view().active)return;const t=duration?Math.min(1,(performance.now()-start)/duration):1;editField(begin+(target-begin)*(t*t*(3-2*t)));if(t>=1)break;await new Promise(r=>setTimeout(r,90));}while(true);if(token===epoch){setQuote(q);return releaseField('astra');}}
async function schedule(q,token=epoch){if(token!==epoch||!(game.view().active||planAssist))return;setQuote(q);const bending=q.kind==='coast'&&game.view().field&&game.view().time<game.view().field.until-1e-9;const seconds=q.kind==='coast'||q.kind==='drift'?(bending||q.kind==='drift'?(scene.reduced?.5:.75):1):q.kind==='calibrate'?4:q.kind==='brake'?2:2.5;if(!await waitPreview(seconds,token))return;try{commitReviewed(q,{source:helm||planAssist?'astra':'route',investigation:q.kind==='calibrate',token});if(q.kind==='drift')driftRemaining=Math.max(0,driftRemaining-q.cost.lifetime);quote=null;preview=null;comparison=null;if(q.kind==='calibrate'){say('Position verified. We can shape a ship-controlled gravity field to change our course.','MEASURED & SOLVED');card({state:'POSITION VERIFIED',title:'Position verified.',description:'Home direction is now known.',metrics:[['Investigation paid',`${fmt(game.view().ledger.filter(l=>['identify','calibrate'].includes(l.kind)).reduce((n,l)=>n+l.cost.credits,0))} credits`],['Fuel / time spent','0 / 0']],evidence:'Four observations solved position and orientation; four held-out landmarks verified them. The home bearing is now supported by that solution.'});}if(q.kind==='extract'){say(`${game.view().report?.name??'The asteroid'} is mined out. Recovered ${q.reward.fuel} fuel and ${q.reward.credits} credits.`,'VERIFIED EXTRACTION');if(plannedOnward){game.preference('less-fuel');plannedOnward=false;}}render();if(game.view().phase==='at-star'){cancelWork();lastProposal=null;scene.clearOverlays();render();starArrival();return;}if(game.view().phase==='arrived'){cancelWork();selected=null;skyExploration=false;constellationSelection=null;scene.clearOverlays();render();say('We made it home.','VERIFIED ARRIVAL');return;}return proceed(token);}catch(e){fail(e);}}
async function proceed(token=epoch){if(token!==epoch)return;if(game.view().mode==='plan'){if(planAssist)return decide('Propose a route for review. Remain in Plan.');return;}if(!game.view().active||(!helm&&!routeAuthority))return;const v=game.view(),opts=game.options();if(driftRemaining>1e-9)return schedule(game.driftQuote(Math.min(.125,driftRemaining)),token);if(v.target)return schedule(game.quote(opts[0]),token);if(v.phase==='at-stop'&&automaticMining)return schedule(game.quote('extract'),token);if(v.phase==='mined'&&v.objective==='yolo'){pause();game.setMode('plan');lastProposal=null;card({title:`${v.report.name} is mined out.`,description:'Pick another rock, or see what the trip home would cost.',actions:[['Choose another asteroid',openMission],['Plot a course home',plotHome]]});openMission();return;}if(v.phase==='mined'){const q=game.quote('launch-home',{speed:.025});return schedule(q,token);}if(helm)return decide();game.pause();render();}
function takeHelm(message){message??=`Take the helm and follow my current field preview if it is affordable. ${game.attempt()?'Use the preserved push as a reference. ':''}Respect my latest priorities; ${game.view().objective==='explore'?`Our objective is to visit ${game.view().destinationStar.name} and stop after verified braking.`:game.view().objective==='yolo'?'Our objective is YOLO mining: reach the selected asteroid, brake and extract, then stop for my next target choice.':'Go directly home unless I choose a resource stop.'}`;if(game.view().active||request)pause(true);try{uiError=false;game.setMode('drive');establishBudget();helm=true;render();decide(message);}catch(e){fail(e);}}
function helpPlan(message='Help me plan a direct gravity route home. Investigate if needed, then propose without movement.') {const pending=fuelRevisionPending;pause(true);fuelRevisionPending=pending;try{syncBudget();planAssist=true;uiError=false;render();decide(message);}catch(e){fail(e);}}
function send(message){if(game.view().phase==='arrived')return;const fuel=/less fuel/i.test(message);if(fuel&&fuelRevisionPending)return;say(message,'YOU','user');const delegated=helm;pause(true);fuelRevisionPending=fuel;uiError=false;
 if(['at-star','mined'].includes(game.view().phase)){decide(message,true);}else if(game.view().mode==='plan'){if(game.view().calibration)helpPlan(message);else decide(message,true);}else if(delegated)takeHelm(message);else decide(message,true);render();}
$('#help-plan').onclick=()=>helpPlan();
let sliderArmed=false,sliderDrag=null;
const slider=$('#field-strength');
slider.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const value=Number(slider.value);beginGesture();sliderArmed=true;sliderDrag={id:e.pointerId,x:e.clientX,value};slider.setPointerCapture(e.pointerId);};
slider.onpointermove=e=>{if(!sliderDrag||e.pointerId!==sliderDrag.id)return;sliderDrag.value=Math.max(0,Math.min(1000,sliderDrag.value+(e.clientX-sliderDrag.x)/slider.getBoundingClientRect().width*1000*(e.shiftKey?.1:1)));sliderDrag.x=e.clientX;editField(.07-sliderDrag.value/1000*.05);};
slider.oninput=()=>{const value=Number(slider.value);if(!sliderArmed){beginGesture();sliderArmed=true;}editField(.07-value/1000*.05);};
slider.onpointerup=e=>{if(!sliderDrag||sliderDrag.id!==e.pointerId)return;sliderDrag=null;sliderArmed=false;if(slider.hasPointerCapture(e.pointerId))slider.releasePointerCapture(e.pointerId);releaseField('human');};
slider.onpointercancel=slider.onlostpointercapture=()=>{sliderDrag=null;sliderArmed=false;handleEditing=false;};
slider.onkeydown=e=>{if(e.key==='Escape'){const id=sliderDrag?.id;sliderDrag=null;sliderArmed=false;handleEditing=false;if(id!==undefined&&slider.hasPointerCapture(id))slider.releasePointerCapture(id);}if(e.key==='Enter'&&sliderArmed){e.preventDefault();sliderArmed=false;releaseField('human');}};
function changeJourneyMode(mode){const old=quote;pause(true);game.setMode(mode);try{syncBudget();if(old?.kind.startsWith('gravity-'))setQuote(game.fieldQuote({destination:destinationOf(old),speed:old.detail.requestedSpeed,centerShip:old.detail.centerShip}));else if(old?.kind==='experiment')setQuote(game.rawQuote({impulse:old.detail.impulse,flightYears:2}));else{quote=null;preview=null;}}catch(e){quote=null;preview=null;say(e.message,'PAUSED');}if(!quote)card({state:mode==='plan'?'PLAN · PAUSED':'DRIVE · YOU HAVE THE HELM',title:game.view().target?'Journey paused.':'Try a push',description:game.view().target?'Current position and spending are preserved. Astra can resume this route when you give the helm.':'Drag to explore a proposal.'});render();}
$('#plan-mode').onclick=()=>changeJourneyMode('plan');$('#drive-mode').onclick=()=>changeJourneyMode('drive');
for(const k of ['fuel','credits','lifetime'])$('#budget-'+k).onchange=()=>{try{syncBudget();quote=null;preview=null;render();}catch(e){fail(e);}};
$('#delegate').onclick=()=>takeHelm();$('#interrupt').onclick=()=>{pause(true);say('Paused. You have the helm.','HELM INTERRUPTED');};$('#chat-form').onsubmit=e=>{e.preventDefault();const m=$('#message').value.trim();if(m){$('#message').value='';send(m);}};function requestLessFuel(){send(game.view().mode==='plan'?'Use less fuel and keep the revised route in Plan.':'Use less fuel and keep driving.');}revisionButton.onclick=requestLessFuel;$('#route-question').onclick=()=>{$('#message').value='Can we keep at least 140 years with this route?';$('#message').focus();};$('#skip-stop').onclick=()=>{if(replayChapter==='mining'&&!game.view().target){pause();automaticMining=false;plannedOnward=false;game.preference('less-fuel');setQuote(game.fieldQuote({speed:.025}));say('Stop declined. The purchased report remains spent; this direct field route is still affordable.','COMPUTED REPLAY');}else send('Skip the asteroid stop and take us home.');};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(game.view().active||request)){$('#interrupt').click();}});
$('#select-mode').onclick=()=>setMode('select');$('#brush-mode').onclick=()=>setMode('brush');$('#look-mode').onclick=()=>setMode('look');function setMode(m){scene.setMode(m);$('#journey-map').setAttribute('aria-label',m==='select'?'Select a catalogue light. Ringed bright lights are suggested targets; hover any catalogue star to highlight it. Selection is free.':m==='look'?'Move view. Drag to rotate the camera; this does not select or push.':'Preview a push. Drag from the ship; release follows Plan or Drive.');for(const id of ['select','brush','look']){$('#'+id+'-mode').classList.toggle('active',id===m);$('#'+id+'-mode').setAttribute('aria-pressed',String(id===m));}}$('#recenter').onclick=()=>scene.recenter();$('#zoom-in').onclick=()=>scene.zoomBy(1.25);$('#zoom-out').onclick=()=>scene.zoomBy(.8);$('#fit-route').onclick=()=>scene.fitRoute();
let detailsOpener;function openDetails(event){detailsOpener=event?.currentTarget??document.activeElement;$('#detail-drawer').hidden=false;$('#details-toggle').setAttribute('aria-expanded','true');$('#close-details').focus();}$('#details-toggle').onclick=openDetails;$('#close-details').onclick=()=>{$('#detail-drawer').hidden=true;$('#details-toggle').setAttribute('aria-expanded','false');detailsOpener?.focus();};$('#detail-drawer').addEventListener('keydown',e=>{if(e.key==='Escape')$('#close-details').click();});
$('#undo').onclick=()=>{const edit=fieldEdit;pause();try{game.undo();skyExploration=false;constellationSelection=null;acceptedFuelRevision=false;recordedComparisons=[];previousAlternativePath=null;flightPath=null;tracers=null;comparison=null;history=[];say('Rewound the field edit and every later checkpoint. Time, resources, deposit and ledger are restored together.','UNDO · COMPLETE STATE RESTORED');render();const destination=game.view().objective==='explore'?'star':automaticMining&&game.view().report?'asteroid':'home';let q=game.fieldQuote({destination,speed:edit?.speed});if(edit?.offset)q=game.fieldQuote({destination,speed:edit.speed,centerShip:V.add(q.detail.centerShip,edit.offset)});setQuote(q);scene.fitRoute();}catch(e){fail(e);}};
function reset(random=false,demo=isDemo){pause();skyExploration=false;constellationSelection=null;missionRevision=-1;missionCache=null;missionDismissed=false;routeBaseline=null;isDemo=demo;if(random)seed=Math.floor(Math.random()*2**32);else if(demo)seed=DEMO.seed;game=new Journey(features,demo?{...DEMO,seed}:{seed,mode:'plan'});hasDelegated=false;fuelRevisionPending=false;acceptedFuelRevision=false;uiError=false;history=[];quote=null;preview=null;comparison=null;attemptPath=null;stroke=null;tracers=null;flightPath=null;fieldEdit=null;selected=null;automaticMining=false;plannedOnward=false;lastProposal=null;lastSkyTime=-1;recordedComparisons=[];previousAlternativePath=null;$('#conversation').replaceChildren();for(const [k,n] of Object.entries(demo?{...DEMO.balance}:{fuel:75,credits:20,lifetime:900}))$('#budget-'+k).value=n;$('#preset-label').textContent=demo?'Demo preset · 22 fuel / 15 credits / 500 years':'Random run · original 100 fuel / 30 credits / 1,000 years';say("I can identify a star, then help us find home.",'ASTRA · READY');scene.recenter();setMode('select');card({state:'',title:'',description:'',actions:[['Select a bright light',selectBrightLight]],evidence:'Preview a push: drag outward from the ship. Move view rotates the camera. Release keeps a free preview; applying it spends the quote.'});syncBudget();render();}
$('#export-ledger').onclick=()=>{const blob=new Blob([JSON.stringify({model:'astralogy-v2',experience,sessionId,...game.view(),currentPreview:quote,camera:scene.cameraState(),skyExploration,attempt:game.attempt(),humanRevisions:recordedComparisons},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brush-journey-record.json';a.click();URL.revokeObjectURL(url);};for(const [k,n] of Object.entries(DEMO.balance))$('#budget-'+k).value=n;syncBudget();render();

const chapters=[
 {id:'revise',title:'Shape a route',description:'Prepared position and route. Drag the handle, ask Astra about lifetime, then hand over the helm.'},
 {id:'locate',title:'Locate ourselves',description:'Unknown sky. Identify a star and ask live Astra to locate home.'},
 {id:'mining',title:'Home can wait',description:'Prepared position. Choose a finite asteroid, shape its approach and mine it.'},
 {id:'travel',title:'Arrival',description:'A paid field is already in place. Resume the actual flight and verify arrival.'},
 {id:'complete',title:'Complete journey',description:'Start with an unknown sky and make every decision.'},
];
let selectedChapter='revise';
function inspectChapter(id){const c=chapters.find(c=>c.id===id)??chapters[0];selectedChapter=c.id;$('#chapter-title').textContent=c.title;$('#chapter-question').textContent=c.description;$('#chapter-evidence').replaceChildren();for(const b of $('#chapter-tabs').children)b.setAttribute('aria-pressed',String(b.dataset.chapter===c.id));}
$('#chapters-toggle').onclick=()=>{$('#journey-menu').close();$('#chapter-tabs').replaceChildren();for(const c of chapters){const b=document.createElement('button');b.textContent=c.title;b.dataset.chapter=c.id;b.onclick=()=>inspectChapter(c.id);$('#chapter-tabs').append(b);}inspectChapter(replayChapter??'revise');$('#chapters-dialog').showModal();};
$('#chapter-replay').onclick=()=>{$('#chapters-dialog').close();startFresh('demo',selectedChapter);};
$('#chapters-close').onclick=()=>$('#chapters-dialog').close();
function setupReplay(){
 const chapter=replayChapter==='bend'?'revise':replayChapter;
 if(!chapter||['locate','complete'].includes(chapter))return;
 try{
  commitReviewed(game.quote('calibrate'),{source:'human',investigation:true});
  if(chapter==='mining'){say('Prepared position. The ship has not moved. Choose a rock to make mining the mission.','DEMO SETUP');render();openMission();return;}
  const q=game.fieldQuote({speed:chapter==='travel'?.025:.04});setQuote(q);
  if(chapter==='travel'){
   flightPath=preview?.proposed.path;commitReviewed(q,{source:'human',enterDrive:true});game.pause();game.setMode('plan');quote=null;preview=null;
   card({state:'Demo · prepared flight',title:'Ready to fly.',description:'Calibration and the field are paid. Take the helm to continue the actual flight.',evidence:'Setup used real engine actions. The ship has not advanced in time. Arrival still requires coasting and braking.'});
   say('Prepared flight. Give Astra the helm to continue.','DEMO SETUP');
  }else say('Prepared route. Drag the diamond grip to shape our ship-controlled gravity field.','DEMO SETUP');
  render();
 }catch(e){fail(e);}
}
$('#return-replay').onclick=()=>{if(window.opener){window.opener.focus();window.close();}};

function selectLight(token){if(game.view().phase==='arrived')return;if(game.view().active||request)pause(true);selected=token;render();const known=game.view().identifiedLights.find(x=>x.observationId===token);if(known)return showIdentification(known);
 card({state:'',title:'Identify this star',description:'Identity first. Position comes next.',metrics:[],actions:[['Identify light · 1 credit',()=>{try{cancelWork();const q=game.identifyQuote(token);commitReviewed(q,{source:'human',investigation:true});quote=null;preview=null;render();showIdentification(game.view().identifiedLights.find(x=>x.observationId===token));}catch(e){fail(e);}}]],evidence:'Selection is bound to an opaque observation token for the clicked catalogue point, not the public array order. The first tag credit counts toward the six-credit location investigation.'});
}
function showIdentification(light){const star=features.find(f=>f.id===light.catalogueId);if(!star)return;const [ra,dec]=star.geometry.coordinates,con=Constellation(ra/15,dec),remaining=game.view().calibrationCredits;
 card({state:'Star identified',title:`HIP ${light.catalogueId} · ${con.name}`,description:game.view().calibration?'This tagged light is part of the measured sky.':'Star identified. Next, measure our position and home direction.',metrics:[['Tag paid','1 credit'],['Location investigation',game.view().calibration?'Complete':`${remaining} credits left`]],actions:game.view().calibration?[['Inspect measurements',openDetails]]:[[`Locate ourselves · ${remaining} credits`,()=>{if(false){try{commitReviewed(game.quote('calibrate'),{source:'human',investigation:true});render();say('Position and orientation solved from measured ranges and bearings; four held-out stars check the fix.','COMPUTED REPLAY');card({state:'POSITION VERIFIED',title:'Now home has a direction.',description:`Held-out residual ${game.view().calibration.heldOutResidual.toExponential(2)} ly.`,actions:[['Inspect measurements',openDetails]],evidence:'The same initial position and velocity are preserved. The first identification credit counted toward calibration. Each additional identification remains separately charged; no fuel or journey time was spent.'});}catch(e){fail(e);}}else helpPlan();}]],evidence:'HIP identity is supplied by the synthetic tag instrument. Constellation membership uses bundled Astronomy Engine IAU boundary lookup on the real catalogue J2000 coordinates. Reference pattern is not registered onto the unknown ship view.'});
 renderConstellationPreview($('#star-context'),{pattern:constellationLines.find(c=>c.id===con.symbol),coordinates:[ra,dec],id:light.catalogueId,name:con.name});
}

function selectBrightLight(){setMode('select');const token=scene.visibleLight();if(token)selectLight(token);else say('Move view to find another ringed catalogue light.','SELECT A LIGHT');}
$('#investigate-stop').onclick=()=>{pause(true);try{syncBudget();commitReviewed(game.quote('survey'),{source:'human',investigation:true});render();helpPlan('I paid for the asteroid report. Evaluate mining against my current field preview and priorities, including full detour, extraction, onward flight and braking. Recommend a stop only if justified; otherwise explain why we should skip it. Keep this in Plan.');}catch(e){fail(e);}};
if(false){card({state:'',title:'',description:'',actions:[['Select a bright light',selectBrightLight]],evidence:'Rings mark selectable catalogue stars. Background dust is decorative. Selection is free; identification costs one credit.'});setMode('select');render();}

function openMission(){
 pause(true);const v=game.view(),f=forecast();$('#mission-targets').replaceChildren();
 $('#mission-title').textContent=v.objective==='yolo'?'Pick another rock.':'Home can wait.';
 $('#mission-description').textContent=f?.blocked??(v.objective==='yolo'?'Choose the next target from our current position.':f?.dire?(f.homeFeasible?'A route home fits, but the tested routes leave tight reserves. Or… we could go asteroid mining.':'The tested home routes do not fit our limits. A reachable rock could be our next destination.'):'Change the mission: roam, mine, and see what happens. Getting there is the expensive part.');
 let usable=0;
 for(const a of f?.targets??[]){const r=a.routes.find(r=>r.affordable),b=document.createElement('button');b.textContent=r?`${a.name} · ${fmt(r.fuel,2)} fuel + 2 credits · ${fmt(r.years)} years → ${a.deposit.fuel} fuel / ${a.deposit.credits} credits`:`${a.name} · ${a.deposit.fuel?'Beyond current limits':'Mined out'}`;b.disabled=!r;if(r)usable++;b.onclick=()=>chooseAsteroid(a.id,r.speed);$('#mission-targets').append(b);}
 if(!usable&&!f?.blocked)$('#mission-description').textContent+=' No unmined target currently fits. Check spending limits and inventory; rewards cannot pay the approach.';
 const canExpand=['fuel','credits','lifetime'].some(k=>v.resources[k]+v.spent[k]>v.budget[k]+1e-8);
 $('#mission-renew').hidden=!canExpand||!!f?.blocked;$('#mission-renew').textContent=`Use current inventory as limits · ${fmt(v.resources.fuel,2)} fuel / ${fmt(v.resources.credits)} credits / ${fmt(v.resources.lifetime)} years remaining`;
 if(!$('#mission-dialog').open)$('#mission-dialog').showModal();
}
function chooseAsteroid(id,speed){try{pause();skyExploration=false;constellationSelection=null;missionDismissed=true;game.changeObjective('yolo',id);game.setMode('plan');automaticMining=false;plannedOnward=false;lastProposal=null;routeBaseline=null;$('#mission-dialog').close();setQuote(game.fieldQuote({destination:'asteroid',speed}));scene.fitRoute();say(`Home can wait. Let's look at ${game.view().report.name}.`,'MISSION CHANGED');helpPlan('I chose YOLO mining and this asteroid. Review my exact currentPreview approach, braking and extraction costs. Keep it in Plan. Home is no longer the current objective.');}catch(e){fail(e);}}
function plotHome(){try{pause();skyExploration=false;constellationSelection=null;game.changeObjective('home');game.setMode('plan');automaticMining=false;plannedOnward=false;lastProposal=null;routeBaseline=null;$('#mission-dialog').close();const f=forecast(),r=f.home.find(r=>r.affordable)??f.home[0];if(!r)throw Error('No supported home approach from this state.');setQuote(r.kind==='launch-home'?game.quote('launch-home',{speed:r.speed}):game.fieldQuote({destination:'home',speed:r.speed}));helpPlan('I changed the objective back to home. Evaluate this route from our actual current position, velocity and remaining spending limits. Stay in Plan and be honest if it does not fit.');}catch(e){fail(e);}}
$('#mission-change').onclick=openMission;$('#mission-home').onclick=plotHome;
$('#mission-renew').onclick=()=>{const v=game.view();game.setBudget(Object.fromEntries(['fuel','credits','lifetime'].map(k=>[k,v.spent[k]+v.resources[k]])));for(const k of ['fuel','credits','lifetime'])$('#budget-'+k).value=game.view().budget[k];say('Spending limits updated to the inventory you authorized.','LIMITS UPDATED');openMission();};

// Sessions are retained in this tab only. Keep actual engine instances and UI choices;
// never serialize execution authority or substitute a prepared state for Play.
function captureSession(){
 const pendingDrift=driftRemaining;pause(true);
 return {skyExploration,constellationSelection,game,sessionId,replayChapter,seed,isDemo,hasDelegated,routeBaseline,missionDismissed,
  history:[...history],quote,lastProposal,attemptPath,stroke,flightPath,fieldEdit,selected,
  automaticMining,plannedOnward,recordedComparisons,previousAlternativePath,acceptedFuelRevision,
  currentCard,conversation:$('#conversation').innerHTML,message:$('#astra-message').textContent,
  interaction:scene.mode,camera:scene.cameraState(),driftRemaining:pendingDrift};
}
function restoreSession(s){
 ({skyExploration,constellationSelection,game,sessionId,replayChapter,seed,isDemo,hasDelegated,routeBaseline,missionDismissed,history,
 lastProposal,attemptPath,stroke,flightPath,fieldEdit,selected,automaticMining,plannedOnward,
 recordedComparisons,previousAlternativePath,acceptedFuelRevision,currentCard}=s);
 missionRevision=-1;missionCache=null;lastSkyTime=-1;uiError=false;fuelRevisionPending=false;
 quote=null;preview=null;comparison=null;tracers=null;fieldGoal=null;driftRemaining=s.driftRemaining;
 game.setMode('plan');$('#conversation').innerHTML=s.conversation;$('#astra-message').textContent=s.message;
 for(const k of ['fuel','credits','lifetime'])$('#budget-'+k).value=game.view().budget[k];
 scene.restoreCamera(s.camera);setMode(s.interaction);if(currentCard)card(currentCard);
 try{
  const v=game.view(),q=s.quote;
  if(v.target)setQuote(game.quote(game.options()[0]));
  else if(q?.kind.startsWith('gravity-'))setQuote(game.fieldQuote({destination:destinationOf(q),speed:q.detail.requestedSpeed,centerShip:q.detail.centerShip}));
  else if(q?.kind==='experiment')setQuote(game.rawQuote({impulse:q.detail.impulse,flightYears:2}));
  else if(q&&game.options().includes(q.kind))setQuote(game.quote(q.kind));
  else if(selected&&v.identifiedLights.some(l=>l.observationId===selected))showIdentification(v.identifiedLights.find(l=>l.observationId===selected));
 }catch(e){say(e.message,'PREVIEW NEEDS REVIEW');}
 render();
}
function closeSurfaces(){for(const d of document.querySelectorAll('dialog[open]'))d.close();$('#detail-drawer').hidden=true;$('#details-toggle').setAttribute('aria-expanded','false');}
function switchExperience(next){
 if(!['play','demo'].includes(next)||next===experience)return;
 closeSurfaces();if(experience!=='entry')sessions.set(experience,captureSession());else cancelWork();
 experience=next;const saved=sessions.get(next);
 if(saved)restoreSession(saved);else startFresh(next,next==='demo'?'revise':null);
 renderShell();$('#journey-menu-toggle').focus();
}
function startFresh(next,chapter=null){
 closeSurfaces();cancelWork();experience=next;replayChapter=next==='demo'?(chapter??'revise'):null;
 sessionId=crypto.randomUUID();reset(false,true);setupReplay();scene.fitRoute();renderShell();
}
function renderShell(){
 document.body.dataset.experience=experience;document.body.dataset.sessionId=sessionId;
 $('#experience-entry').hidden=experience!=='entry';$('#flight-deck').inert=experience==='entry';
 $('#experience-label').textContent=experience==='demo'?'DEMO':'PLAY';
 $('#experience-switch').textContent=experience==='demo'?(sessions.has('play')?'Resume Play':'Play'):'Try the demo';
 $('#chapters-toggle').hidden=experience!=='demo';
 $('#replay-label').hidden=experience!=='demo';
 $('#replay-label').textContent=['locate','complete'].includes(replayChapter)?'Demo · complete journey':'Demo · prepared scenario';
 $('#reset').textContent=experience==='demo'?'Restart this demo':'New journey · keep previous';
 $('#restore-previous').hidden=experience!=='play'||!previousPlay;
 $('#session-note').textContent=experience==='demo'?'Demo is separate from Play. Both stay paused when you switch.':'Play is kept while you visit Demo in this tab. Reload starts fresh.';
 $('#return-replay').hidden=true;
}
$('#entry-play').onclick=()=>switchExperience('play');$('#entry-demo').onclick=()=>switchExperience('demo');
$('#experience-switch').onclick=()=>switchExperience(experience==='play'?'demo':'play');
$('#journey-menu-toggle').onclick=()=>{$('#journey-menu').showModal();};
$('#reset').onclick=()=>{if(experience==='play')previousPlay=captureSession();startFresh(experience,replayChapter);};
$('#restore-previous').onclick=()=>{const current=captureSession(),old=previousPlay;previousPlay=current;closeSurfaces();restoreSession(old);};
if(replayChapter)startFresh('demo',replayChapter==='bend'?'revise':replayChapter);
else renderShell();

function renderMissionOffer(){
 const v=game.view(),eligible=experience==='play'&&v.calibration&&v.objective==='home'&&v.phase!=='arrived'&&!v.target&&lastProposal&&!missionDismissed;
 const f=eligible?forecast():null,show=!!(f?.dire&&f.targets.some(a=>a.routes.some(r=>r.affordable)));
 $('#mission-offer').hidden=!show;$('#mission-stay').hidden=!show;
 if(show)$('#mission-offer').textContent=f.homeFeasible?'A route home fits, but reserves will be tight. Or… we could go asteroid mining.':'The tested routes home do not fit our limits. A reachable asteroid could be our next stop.';
}
$('#mission-stay').onclick=()=>{missionDismissed=true;render();};

function starArrival(){game.setMode('plan');skyExploration=true;setMode('look');card({state:'Arrival verified',title:game.view().destinationStar.name,description:'We are stopped near the star system. Look around its sky, or choose another destination.',actions:[['Browse constellations',openSky],['Plot a course home',plotHome]],evidence:`Distance ${V.norm(V.sub(game.view().position,game.view().destinationStar.position)).toExponential(3)} ly; speed ${V.norm(game.view().velocity).toExponential(3)} ly/year. This is a real catalogue star identity. Its depth is simulated. The approach stops 0.01 simulated ly from the star; no surface landing or orbit is simulated.`});say(`${game.view().destinationStar.name} reached. The sky looks different from here.`,'VERIFIED ARRIVAL');render();}
function visitStar(targetId=game.view().identifiedLights.find(l=>l.observationId===selected)?.catalogueId??game.view().destinationStar.id){try{$('#sky-dialog').close();pause();const routes=game.starForecast(targetId),r=routes.find(r=>r.affordable)??routes[0];if(!r)throw Error('No supported star-system approach here. If a field is active, resume to its expiry before changing destination.');skyExploration=false;constellationSelection=null;game.changeObjective('explore',targetId);game.setMode('plan');lastProposal=null;routeBaseline=null;automaticMining=false;plannedOnward=false;setQuote(game.fieldQuote({destination:'star',speed:r.speed}));scene.fitRoute();say(`${game.view().destinationStar.name} is a real catalogue star. This quote covers the simulated approach and stop; a return trip is separate.`,'PLAN');helpPlan(`I chose to visit catalogue star ${game.view().destinationStar.name}. Review this exact approach and braking preview. Stay in Plan. This is a one-way simulated visit; do not promise an affordable return.`);}catch(e){fail(e);}}
$('#visit-star').onclick=()=>visitStar();
let constellationGroups;
function skyGroups(){if(constellationGroups)return constellationGroups;const groups=new Map();for(const f of features){const [ra,dec]=f.geometry.coordinates,c=Constellation(ra/15,dec);if(!groups.has(c.symbol))groups.set(c.symbol,{symbol:c.symbol,name:c.name,stars:[]});groups.get(c.symbol).stars.push(f);}constellationGroups=[...groups.values()].sort((a,b)=>a.name.localeCompare(b.name));return constellationGroups;}
function openSky(){if(!['at-star','arrived'].includes(game.view().phase))return;pause();skyExploration=true;selected=null;scene.clearOverlays();setMode('look');const list=$('#constellation-select');if(!list.options.length)for(const g of skyGroups()){const o=document.createElement('option');o.value=g.symbol;o.textContent=`${g.name} · ${g.stars.length} stars`;list.append(o);}$('#sky-location').textContent=game.view().phase==='arrived'?'At Earth · full available catalogue':`Near ${game.view().destinationStar.name} · full available catalogue`;renderAtlas();render();$('#sky-dialog').showModal();}
function renderAtlas(){const g=skyGroups().find(g=>g.symbol===$('#constellation-select').value);if(!g)return;const patterns=constellationLines.filter(c=>c.id===g.symbol),lines=patterns.flatMap(p=>p.geometry.coordinates);renderConstellationAtlas($('#constellation-atlas'),{lines,stars:g.stars,name:g.name});$('#constellation-count').textContent=`${g.stars.length} available catalogue stars · ${lines.reduce((n,l)=>n+Math.max(0,l.length-1),0)} reference segments`;$('#constellation-stars').replaceChildren();for(const star of [...g.stars].sort((a,b)=>a.properties.mag-b.properties.mag)){const p=document.createElement('p');p.textContent=`HIP ${star.id} · magnitude ${fmt(star.properties.mag,2)} · RA ${fmt(star.geometry.coordinates[0],2)}° / Dec ${fmt(star.geometry.coordinates[1],2)}°`;if(game.view().phase==='at-star'&&star.id!==game.view().destinationStar.id){const b=document.createElement('button');b.textContent=`Preview visit to HIP ${star.id}`;b.onclick=()=>visitStar(star.id);p.append(document.createElement('br'),b);}$('#constellation-stars').append(p);}}
$('#constellation-select').onchange=renderAtlas;$('#browse-sky').onclick=openSky;
$('#show-local-sky').onclick=()=>{const g=skyGroups().find(g=>g.symbol===$('#constellation-select').value),ids=new Set(g.stars.map(s=>s.id));constellationSelection={name:g.name,stars:game.chartedSky().filter(s=>ids.has(s.catalogueId))};$('#sky-dialog').close();render();$('#scene-description').textContent=`${g.name}: highlighted catalogue members in this local sky. Move view to look around.`;$('#journey-map').focus();};
